class BlankNodeGraphExistenceProbeTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();

	@Test
	void fixedGraphExistenceStopsAfterFirstStatementInArrayContext() {
		assertBoundedProbe(false);
	}

	@Test
	void boundGraphExistencePreservesCollidingUserVariableNames() {
		assertBoundedProbe(true);
	}

	private static void assertBoundedProbe(boolean boundGraph) {
		Resource graph = VF.createBNode("graph");
		var source = new ProbeSource(graph);
		var strategy = new DefaultEvaluationStrategy(source, null);
		Value node = VF.createBNode("unknown-node");
		String graphName = "_zero_length_graph_s";
		Var graphVar = boundGraph ? Var.of(graphName) : Var.of(graphName, graph);
		var path = new ZeroLengthPath(Scope.NAMED_CONTEXTS, Var.of("_zero_length_graph_p", node), Var.of("o"),
				graphVar);
		var input = new MapBindingSet();
		if (boundGraph) {
			input.addBinding(graphName, graph);
		}
		try (var rows = strategy.precompile(new QueryRoot(path)).evaluate(input)) {
			assertTrue(rows.hasNext());
			var row = rows.next();
			assertEquals(node, row.getValue("o"));
			if (boundGraph) {
				assertEquals(graph, row.getValue(graphName));
			}
			assertFalse(rows.hasNext());
		}
		assertTrue(source.reads <= 1, "a fixed graph existence probe must not exhaust its statements");
		assertTrue(source.closed);
	}

	private static final class ProbeSource implements TripleSource {
		private final Resource graph;
		private int reads;
		private boolean closed;

		private ProbeSource(Resource graph) {
			this.graph = graph;
		}

		public ValueFactory getValueFactory() {
			return VF;
		}

		public CloseableIteration<? extends Statement> getStatements(Resource s, IRI p, Value o,
				Resource... contexts) {
			return new CloseableIteration<Statement>() {
				private int remaining = 100;

				public boolean hasNext() {
					return remaining > 0;
				}

				public Statement next() {
					remaining--;
					reads++;
					return VF.createStatement(VF.createIRI("urn:s"), VF.createIRI("urn:p"), VF.createLiteral(1), graph);
				}

				public void remove() {
					throw new UnsupportedOperationException();
				}

				public void close() {
					closed = true;
				}
			};
		}
	}
}
